mapper.select:
select *
from ${tableName} a
where a.enterprise_code = #{enterpriseCode}
  and a.primary_key = #{primaryKey}
  and a.delete_flag = false

select sum(inspect_num)
from ${tableName}
where enterprise_code = #{enterpriseCode}
  and batch_no = #{batchNo}
  and inspect_user = #{userCode}
  and delete_flag = false

WITH t as (select count(1)
           from ${dispatcherTableName}
           where process_main_id = #{mainId}
             and delete_flag = false),
     t1 as (select count(1)
            from (select DISTINCT process_main_id, inspect_user, status
                  from ${reportTableName}
                  where process_main_id = #{mainId}
                    and delete_flag = false
                    and status = 50))
select t.* = t1.*
from t,
     t1

mapper.update:
update ${tableName}
set status = #{status}
where enterprise_code = #{enterpriseCode}
  and batch_no = #{batchNo}
  and inspect_user = #{userCode}
